#include "fast_deblur/fast_deblur.hpp"

#include <nlohmann/json.hpp>
#include <opencv2/imgcodecs.hpp>
#include <opencv2/imgproc.hpp>

#include <cctype>
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

namespace fs=std::filesystem;using json=nlohmann::json;
namespace {
struct Metrics{std::string image,variant;double runtime_ms{},reblur_rmse{};fast_deblur::ArtifactDiagnostics artifacts;std::string path;};
cv::Mat readRgb(const fs::path& path){cv::Mat bgr=cv::imread(path.string(),cv::IMREAD_COLOR);if(bgr.empty())throw std::runtime_error("cannot read "+path.string());cv::Mat rgb;cv::cvtColor(bgr,rgb,cv::COLOR_BGR2RGB);rgb.convertTo(rgb,CV_32FC3,1.0/255.0);return rgb;}
void writeRgb(const fs::path& path,const cv::Mat& rgb){cv::Mat x;cv::max(rgb,0.0,x);cv::min(x,1.0,x);x.convertTo(x,CV_8UC3,255.0);cv::Mat bgr;cv::cvtColor(x,bgr,cv::COLOR_RGB2BGR);if(!cv::imwrite(path.string(),bgr,{cv::IMWRITE_JPEG_QUALITY,94}))throw std::runtime_error("cannot write "+path.string());}
void writeKernel(const fs::path& path,const cv::Mat& kernel){double peak=0;cv::minMaxLoc(kernel,nullptr,&peak);cv::Mat vis=kernel.clone();if(peak>0)vis/=static_cast<float>(peak);cv::resize(vis,vis,cv::Size(240,240),0,0,cv::INTER_NEAREST);vis.convertTo(vis,CV_8U,255.0);cv::imwrite(path.string(),vis);}
fast_deblur::DeblurConfig configFromJson(const json& p,bool preview){fast_deblur::DeblurConfig c;c.kernel_size=p.value("kernel_size",25);c.gamma_correct=p.value("gamma",1.0F);c.lambda_dark=p.value("lambda_dark",.004F);c.lambda_grad=p.value("lambda_grad",.004F);c.lambda_tv=p.value("lambda_tv",.003F);c.lambda_l0=p.value("lambda_l0",.0005F);c.weight_ring=p.value("weight_ring",1.0F);c.saturated=p.value("saturated",false);if(preview){c.xk_iter=2;c.max_grad_steps=5;c.max_dark_steps=2;c.saturation_iterations=12;}return c;}
Metrics metric(const std::string& image,const std::string& variant,double runtime,const cv::Mat& source,const cv::Mat& output,const cv::Mat& kernel,const std::string& path){Metrics m;m.image=image;m.variant=variant;m.runtime_ms=runtime;m.path=path;m.reblur_rmse=fast_deblur::rmse(source,fast_deblur::reblur(output,kernel));m.artifacts=fast_deblur::artifactDiagnostics(source,output);return m;}
std::string safeStem(const std::string& name){std::string s=fs::path(name).stem().string();for(char& c:s)if(!(std::isalnum(static_cast<unsigned char>(c))||c=='-'||c=='_'))c='_';return s;}
std::string esc(const std::string& s){std::string o;for(char c:s){if(c=='&')o+="&amp;";else if(c=='<')o+="&lt;";else if(c=='>')o+="&gt;";else if(c=='\"')o+="&quot;";else o+=c;}return o;}
std::string fmt(double v,int p=4){std::ostringstream s;s<<std::fixed<<std::setprecision(p)<<v;return s.str();}
void writeReport(const fs::path& out,const std::vector<Metrics>& metrics,const std::vector<std::string>& images,const std::map<std::string,std::string>& errors,bool preview){
    std::ofstream csv(out/"metrics.csv");csv<<"image,variant,runtime_ms,reblur_rmse,edge_ratio,noise_ratio,highpass_ratio,clipping_growth,path\n";for(const auto&m:metrics)csv<<m.image<<','<<m.variant<<','<<m.runtime_ms<<','<<m.reblur_rmse<<','<<m.artifacts.edge_ratio<<','<<m.artifacts.noise_ratio<<','<<m.artifacts.highpass_ratio<<','<<m.artifacts.clipping_growth<<','<<m.path<<"\n";
    std::map<std::string,std::pair<double,int>> runtime,residual;for(const auto&m:metrics){runtime[m.variant].first+=m.runtime_ms;runtime[m.variant].second++;residual[m.variant].first+=m.reblur_rmse;residual[m.variant].second++;}
    std::ofstream f(out/"index.html");f<<R"(<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>fast-deblur C++ benchmark</title><style>body{font-family:Inter,system-ui,Segoe UI,Arial,sans-serif;margin:0;background:#fff;color:#17202a}main{max-width:1500px;margin:auto;padding:32px}h1{font-size:34px;margin-bottom:6px}.sub{color:#566573;max-width:1000px;line-height:1.55}.summary{display:flex;gap:14px;flex-wrap:wrap;margin:24px 0}.pill{border:1px solid #dfe6e9;border-radius:12px;padding:12px 16px;min-width:180px}.pill b{display:block;font-size:20px;margin-top:4px}.case{border-top:1px solid #e8ecef;padding:28px 0}.grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.panel{border:1px solid #e1e6ea;border-radius:12px;overflow:hidden;background:#fafbfc}.panel h3{font-size:13px;margin:0;padding:9px 11px;background:#f3f5f7}.panel img{display:block;width:100%;aspect-ratio:4/3;object-fit:contain;background:#fff}.metrics{font-size:12px;padding:9px 11px;line-height:1.5;color:#3c4a57}.kernels{display:flex;gap:12px;margin-top:12px}.kernel img{width:120px;height:120px;image-rendering:pixelated;border:1px solid #ddd}.error{padding:12px;background:#fff2f0;border:1px solid #ffccc7;border-radius:8px}.note{font-size:13px;color:#65717c}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.grid{grid-template-columns:1fr}main{padding:18px}}</style></head><body><main>)";
    f<<"<h1>fast-deblur C++ benchmark</h1><p class='sub'>"<<(preview?"Preview benchmark with capped iteration counts.":"Full-quality native-resolution benchmark with uncapped optimization loops.")<<" The <b>MATLAB parity</b> column disables robust heuristics and follows the translated legacy numerical path. The <b>robust baseline</b> ports the current Python method; Annealed PnP and Dual-Extreme reuse its independently estimated PSF. Saved upstream outputs are not used as inference targets.</p>";
    f<<"<div class='summary'><div class='pill'>Images<b>"<<images.size()<<"</b></div>";for(const auto&[v,r]:runtime)f<<"<div class='pill'>"<<esc(v)<<" avg runtime<b>"<<fmt(r.first/r.second,1)<<" ms</b><span class='note'>mean reblur RMSE "<<fmt(residual[v].first/residual[v].second,5)<<"</span></div>";f<<"</div>";
    auto find=[&](const std::string&i,const std::string&v)->const Metrics*{for(const auto&m:metrics)if(m.image==i&&m.variant==v)return &m;return nullptr;};
    for(const auto&name:images){std::string stem=safeStem(name);f<<"<section class='case'><h2>"<<esc(name)<<"</h2>";if(auto it=errors.find(name);it!=errors.end()){f<<"<div class='error'>"<<esc(it->second)<<"</div></section>";continue;}f<<"<div class='grid'><div class='panel'><h3>Observed source</h3><img loading='lazy' src='images/"<<stem<<"_source.jpg'></div>";for(const auto&v:std::vector<std::pair<std::string,std::string>>{{"matlab-parity","MATLAB parity"},{"baseline","Robust baseline"},{"annealed-pnp","Annealed PnP"},{"extreme-channel","Dual-Extreme"}}){const Metrics*m=find(name,v.first);f<<"<div class='panel'><h3>"<<v.second<<"</h3><img loading='lazy' src='images/"<<stem<<"_"<<v.first<<".jpg'>";if(m)f<<"<div class='metrics'>runtime "<<fmt(m->runtime_ms,1)<<" ms<br>reblur RMSE "<<fmt(m->reblur_rmse,5)<<"<br>edge ×"<<fmt(m->artifacts.edge_ratio,2)<<" · noise ×"<<fmt(m->artifacts.noise_ratio,2)<<"<br>high-pass ×"<<fmt(m->artifacts.highpass_ratio,2)<<" · clip +"<<fmt(m->artifacts.clipping_growth,3)<<"</div>";f<<"</div>";}f<<"</div><div class='kernels'><div class='kernel'><b>Parity PSF</b><br><img src='images/"<<stem<<"_parity_kernel.png'></div><div class='kernel'><b>Robust PSF</b><br><img src='images/"<<stem<<"_robust_kernel.png'></div></div></section>";}
    f<<"<p class='note'>Metrics are reference-free diagnostics. Reblur RMSE measures forward-model consistency; edge/noise/high-pass ratios and clipping growth flag common over-deconvolution artifacts. Refinement runtimes are incremental and do not include baseline PSF estimation.</p></main></body></html>";
}
}  // namespace

int main(int argc,char**argv){try{fs::path data="testdata/upstream/dataset/image",profiles="benchmark_profiles.json",out="report";int limit=0;bool preview=false;for(int i=1;i<argc;++i){std::string a=argv[i];auto val=[&](){if(++i>=argc)throw std::invalid_argument("missing value for "+a);return std::string(argv[i]);};if(a=="--data-dir")data=val();else if(a=="--profiles")profiles=val();else if(a=="--out")out=val();else if(a=="--limit")limit=std::stoi(val());else if(a=="--preview")preview=true;else throw std::invalid_argument("unknown argument "+a);}std::ifstream pf(profiles);if(!pf)throw std::runtime_error("cannot open profiles "+profiles.string());json p;pf>>p;fs::create_directories(out/"images");std::vector<Metrics> metrics;std::vector<std::string> images;std::map<std::string,std::string> errors;int processed=0;for(auto it=p.begin();it!=p.end();++it){if(limit>0&&processed>=limit)break;std::string name=it.key();images.push_back(name);++processed;try{cv::Mat source=readRgb(data/name);std::string stem=safeStem(name);writeRgb(out/"images"/(stem+"_source.jpg"),source);auto cfg=configFromJson(it.value(),preview),parity=cfg;parity.robust_selection=false;parity.retry_gradient_only=false;parity.conservative_restoration=false;auto t0=std::chrono::steady_clock::now();auto pr=fast_deblur::deblur(source,parity,fast_deblur::Method::Baseline);auto t1=std::chrono::steady_clock::now();double pms=std::chrono::duration<double,std::milli>(t1-t0).count();writeRgb(out/"images"/(stem+"_matlab-parity.jpg"),pr.image);writeKernel(out/"images"/(stem+"_parity_kernel.png"),pr.kernel);metrics.push_back(metric(name,"matlab-parity",pms,source,pr.image,pr.kernel,pr.restoration_path));t0=std::chrono::steady_clock::now();auto base=fast_deblur::deblur(source,cfg,fast_deblur::Method::Baseline);t1=std::chrono::steady_clock::now();double bms=std::chrono::duration<double,std::milli>(t1-t0).count();writeRgb(out/"images"/(stem+"_baseline.jpg"),base.image);writeKernel(out/"images"/(stem+"_robust_kernel.png"),base.kernel);metrics.push_back(metric(name,"baseline",bms,source,base.image,base.kernel,base.restoration_path));t0=std::chrono::steady_clock::now();cv::Mat pnp=fast_deblur::refine(source,base.image,base.kernel,fast_deblur::Method::AnnealedPnP);t1=std::chrono::steady_clock::now();double nms=std::chrono::duration<double,std::milli>(t1-t0).count();writeRgb(out/"images"/(stem+"_annealed-pnp.jpg"),pnp);metrics.push_back(metric(name,"annealed-pnp",nms,source,pnp,base.kernel,"reuse robust PSF"));t0=std::chrono::steady_clock::now();cv::Mat ext=fast_deblur::refine(source,base.image,base.kernel,fast_deblur::Method::ExtremeChannel);t1=std::chrono::steady_clock::now();double ems=std::chrono::duration<double,std::milli>(t1-t0).count();writeRgb(out/"images"/(stem+"_extreme-channel.jpg"),ext);metrics.push_back(metric(name,"extreme-channel",ems,source,ext,base.kernel,"reuse robust PSF"));std::cout<<"completed "<<name<<"\n";}catch(const std::exception&e){errors[name]=e.what();std::cerr<<"failed "<<name<<": "<<e.what()<<"\n";}}writeReport(out,metrics,images,errors,preview);std::cout<<"report: "<<(out/"index.html")<<"\n";return errors.empty()?0:3;}catch(const std::exception&e){std::cerr<<"benchmark: "<<e.what()<<"\n";return 1;}}
